using HospitalManagement.Web.Models; using HospitalManagement.Web.Services; using Microsoft.AspNetCore.Mvc;
namespace HospitalManagement.Web.Controllers;
public class SettingsController:Controller{private readonly HospitalApiService api;public SettingsController(HospitalApiService api)=>this.api=api;[HttpGet]public IActionResult Index()=>View();
[HttpPost][IgnoreAntiforgeryToken]public async Task<IActionResult>Load(){var s=await api.SettingsAsync();var p=await api.ProfileAsync();if(!s.Ok)return StatusCode(502,new{message=s.Message});return Json(new{success=true,data=new SettingsViewModel{HospitalName=s.Data?.HospitalName??"",ContactEmail=s.Data?.ContactEmail??"",ContactPhone=s.Data?.ContactPhone??"",Address=s.Data?.Address??"",Username=p.Data?.Username??"",FullName=p.Data?.FullName??"",Role=p.Data?.Role??""}});}
[HttpPost][IgnoreAntiforgeryToken]public async Task<IActionResult>Save([FromBody]SettingsViewModel model){if(!ModelState.IsValid)return BadRequest(new{message="Please correct the settings before saving."});var r=await api.UpdateSettingsAsync(model);return r.Ok?Json(new{success=true,message="Hospital settings saved."}):BadRequest(new{message=r.Message});}
[HttpPost][IgnoreAntiforgeryToken]public async Task<IActionResult>Profile([FromBody]SettingsViewModel model){if(string.IsNullOrWhiteSpace(model.FullName))return BadRequest(new{message="Full name is required."});var r=await api.UpdateProfileAsync(model);if(!r.Ok)return BadRequest(new{message=r.Message});HttpContext.Session.SetString("FullName",model.FullName);HttpContext.Session.SetString("Role",model.Role);return Json(new{success=true,message="Profile updated successfully."});}
[HttpPost][IgnoreAntiforgeryToken]public async Task<IActionResult>Password([FromBody]ChangePasswordViewModel model){if(!ModelState.IsValid)return BadRequest(new{message="Please enter valid passwords. New password must be at least 6 characters and confirmation must match."});var r=await api.ChangePasswordAsync(model);return r.Ok?Json(new{success=true,message="Password changed successfully."}):BadRequest(new{message=r.Message});}}
